<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {request,mutate,pending,session,checkOperation,retryOperation} from '../api';
import SourceFiles from './SourceFiles.vue';
import {formatBeijingTimestamp} from '../../../../packages/source-client/src/timestamp';
import {HistoricalController,createHistoricalState,historicalBusy,historicalDirty,historicalWritable,historicalStatus,historicalCoverage,historicalToday,historicalOperationTarget,moneyDifference,type HistoricalOrder,type HistoricalSupplyStatus} from '../../../../packages/historical-client/src';
const props=defineProps<{initialOrderId?:string;locked?:boolean}>(),emit=defineEmits<{(e:'busy-changed',value:boolean):void;(e:'failure',value:unknown):void;(e:'openFinance',target:{orderId:string;receivableId?:string}):void}>();
const state=reactive(createHistoricalState(session.value?.user.role!=='salesperson')),ack=ref(false),recovering=ref(false),notFound=ref(false),recoveryError=ref(''),childBusy=ref(false),sources=ref<InstanceType<typeof SourceFiles>|null>(null),linePage=ref(1);
const controller=new HistoricalController(request,(label,path,method,body)=>mutate<HistoricalOrder>(label,path,method,body),state,e=>emit('failure',e));
const busy=computed(()=>historicalBusy(state)||recovering.value||childBusy.value),dirty=computed(()=>historicalDirty(state)),blocked=computed(()=>!!props.locked||busy.value||!!pending.value),navigationLocked=computed(()=>blocked.value||dirty.value||!!state.review||state.correctionOpen),writable=computed(()=>session.value?.user.role==='salesperson'&&historicalWritable(state)),draftWritable=computed(()=>writable.value&&state.detail?.verificationStatus!=='verified'),fieldsLocked=computed(()=>blocked.value||!draftWritable.value||!!state.review),pages=computed(()=>Math.max(1,Math.ceil((state.page?.total||0)/(state.page?.pageSize||20)))),coverage=computed(()=>historicalCoverage(state.form.lines.map(l=>({...l,quantity:l.quantity||null,confirmedQuantity:l.confirmedQuantity||null,unitPrice:l.unitPrice||null})),state.form.confirmedDate||null)),files=computed(()=>sources.value?.sourceFiles||[]),evidence=computed(()=>state.correctionOpen?state.correction.evidenceFileIds:state.form.evidenceFileIds),hospitalOptions=computed(()=>[{id:'',name:'全部可查看医院'},...state.hospitals]),formHospitals=computed(()=>[{id:'',name:'请选择当前负责医院'},...state.hospitals]),linePages=computed(()=>Math.max(1,Math.ceil(state.form.lines.length/10))),visibleLines=computed(()=>state.form.lines.slice((linePage.value-1)*10,linePage.value*10).map((line,i)=>({line,index:(linePage.value-1)*10+i})));
const statuses=[['','全部核实状态'],['pending_verification','待核实'],['verified','已核实'],['draft','草稿']],supplyOptions:[HistoricalSupplyStatus,string][]=[['unknown','未知'],['priced','有供货依据'],['missing','明确全部缺货']];
const picked=(e:unknown)=>Number((e as {detail:{value:string}}).detail.value),dateValue=(e:unknown)=>(e as {detail:{value:string}}).detail.value;
watch(()=>busy.value||dirty.value||!!state.review||state.correctionOpen||!!pending.value,v=>emit('busy-changed',v),{immediate:true,flush:'sync'});watch(()=>state.review,()=>{ack.value=false;});watch(()=>state.detail?.orderId,()=>{linePage.value=1;});
function guard(work:()=>unknown){if(blocked.value)return;try{state.error='';work();}catch(e){state.error=(e as Error).message;}}
async function safely(work:()=>Promise<unknown>){if(blocked.value)return;try{await work();}catch(e){state.error=(e as Error).message;}}
function addLine(){guard(()=>{controller.addLine();linePage.value=linePages.value;});}
function removeLine(index:number){guard(()=>{controller.removeLine(index);linePage.value=Math.min(linePage.value,linePages.value);});}
function supply(index:number,e:unknown){guard(()=>controller.setSupply(index,supplyOptions[picked(e)][0]));}
function toggleEvidence(id:string){if(blocked.value||state.review||!writable.value||state.detail?.verificationStatus==='verified'&&!state.correctionOpen)return;const list=evidence.value,index=list.indexOf(id);index<0?list.push(id):list.splice(index,1);}
async function refresh(){if(navigationLocked.value)return;await safely(()=>state.detail?controller.open(state.detail.orderId):controller.bootstrap());}
async function openAfterRecovery(orderId?:string){controller.discard();if(orderId)await controller.open(orderId,true);else{state.mode='list';await controller.list();}state.notice=state.error?'原操作已确认提交，最新资料读取失败，请重试。':'原操作已确认提交，已读取最新历史资料。';}
async function recover(retry=false){if(props.locked||busy.value||!pending.value)return;const original=pending.value,target=historicalOperationTarget(original);if(!target)return;recovering.value=true;recoveryError.value='';try{const result=retry?await retryOperation<HistoricalOrder>():null,status=retry?'committed':await checkOperation();notFound.value=status==='not_found';if(status==='committed'){recovering.value=false;await openAfterRecovery(result?.orderId||target.orderId);}}catch(e){recoveryError.value=(e as Error).message;emit('failure',e);}finally{recovering.value=false;}}
async function commit(){if(blocked.value||!ack.value)return;try{await controller.commit();}catch{/* original input and pending descriptor are retained */}}
function discard(){if(!blocked.value){controller.discard();linePage.value=1;}}
function finance(){const o=state.detail;if(o&&!navigationLocked.value)emit('openFinance',{orderId:o.orderId,...o.receivable?{receivableId:o.receivable.id}:{}});}
defineExpose({refresh,openAfterRecovery,canLeave:()=>!busy.value&&!dirty.value&&!state.review&&!state.correctionOpen&&!pending.value&&(sources.value?.canLeave()??true)});
onMounted(async()=>{await controller.bootstrap();if(props.initialOrderId)await controller.open(props.initialOrderId);});
watch(()=>props.initialOrderId,id=>{if(id&&!navigationLocked.value)void controller.open(id);});
onBeforeUnmount(()=>{controller.dispose();emit('busy-changed',false);});
</script>
<template>
 <view class="historical-workspace">
  <view class="heading"><text class="eyebrow">专用历史来源 · 仅内部可见</text><text class="title">历史纸单补录与核实</text><text class="help">旧资料先暂存，核实后入账。原账期、逐行结果与实际日期未知时保留未知。</text></view>
  <view v-if="pending&&historicalOperationTarget(pending)" class="warning"><text class="strong">上次历史补录操作结果待核对</text><text class="help">原输入和操作标识已保留；重新提交沿用原请求。</text><view class="actions"><button :disabled="busy||locked" @click="recover()">核对原操作结果</button><button v-if="notFound" :disabled="busy||locked" @click="recover(true)">按原请求重新提交</button></view><text v-if="notFound" class="help">暂未找到已提交结果，可按原请求重试。</text><text v-if="recoveryError" class="error">{{recoveryError}}</text></view>
  <text v-if="state.error" class="error">{{state.error}}</text><text v-if="state.notice" class="notice">{{state.notice}}</text><text v-if="busy" class="help">正在读取或提交，请稍候…</text>
  <view v-if="dirty||state.review||state.correctionOpen" class="warning"><text class="help">本次内容尚未提交，切换前请保存或放弃修改。</text><button size="mini" :disabled="blocked" @click="discard">放弃本次修改</button></view>
  <template v-if="state.mode==='list'">
   <view class="filters"><label><text>医院</text><picker :range="hospitalOptions.map(h=>h.name)" :value="Math.max(0,hospitalOptions.findIndex(h=>h.id===state.filters.hospitalId))" :disabled="blocked" @change="state.filters.hospitalId=hospitalOptions[picked($event)].id"><view class="picker">{{hospitalOptions.find(h=>h.id===state.filters.hospitalId)?.name||'全部可查看医院'}} ›</view></picker></label><label><text>核实状态</text><picker :range="statuses.map(s=>s[1])" :value="Math.max(0,statuses.findIndex(s=>s[0]===state.filters.verificationStatus))" :disabled="blocked" @change="state.filters.verificationStatus=statuses[picked($event)][0]"><view class="picker">{{statuses.find(s=>s[0]===state.filters.verificationStatus)?.[1]}} ›</view></picker></label><label class="wide"><text>订单 / 药品 / 规格</text><input v-model="state.filters.keyword" maxlength="100" :disabled="blocked" placeholder="输入关键字"/></label></view><view class="actions"><button class="primary" :disabled="blocked" @click="safely(()=>controller.list())">查询</button><button v-if="!state.admin" :disabled="blocked" @click="guard(()=>controller.newDraft())">＋ 新建历史补录</button></view>
   <text v-if="state.page" class="help">共 {{state.page.total}} 单 · 金额单位：元</text>
   <view v-for="o in state.page?.items||[]" :key="o.orderId" class="order-row"><view class="row-heading"><text class="strong">{{o.hospitalName}}</text><text class="status">{{historicalStatus(o)}}</text></view><text class="help">{{o.orderNo}}{{o.originalOrderNo?' · 原编号 '+o.originalOrderNo:''}}</text><text class="fact">接收 {{o.receivedDate||'待核实'}} · 原账期 {{o.originalTermDays===null?'待核实':o.originalTermDays+' 天'}}</text><text class="fact">当前金额 {{o.finalAmount===null?'待核实':o.finalAmount+' 元'}} · 有效已收 {{o.receivable?o.receivable.paid+' 元':'核实后入账'}}</text><view class="row-heading"><text class="help">{{o.writable?'当前负责，可处理':'只读查阅'}}</text><button size="mini" :disabled="navigationLocked" @click="safely(()=>controller.open(o.orderId))">查看 / 处理 →</button></view></view><text v-if="state.page&&!state.page.items.length" class="empty">暂无符合筛选的历史补录。</text>
   <view v-if="state.page" class="pagination"><button size="mini" :disabled="navigationLocked||state.page.page<=1" @click="safely(()=>controller.list((state.page?.page||1)-1))">上一页</button><text>{{state.page.page}} / {{pages}}</text><button size="mini" :disabled="navigationLocked||state.page.page>=pages" @click="safely(()=>controller.list((state.page?.page||1)+1))">下一页</button></view><text v-if="state.page" class="help">数据截止 {{formatBeijingTimestamp(state.page.asOf)}}</text>
  </template>
  <template v-else-if="!state.accessBlocked">
   <view class="actions"><button size="mini" :disabled="navigationLocked" @click="safely(()=>controller.home())">← 补录列表</button><button size="mini" :disabled="navigationLocked" @click="refresh">载入最新保存稿</button><button v-if="state.detail?.receivable" size="mini" :disabled="navigationLocked" @click="finance">账期 / 异常 →</button></view>
   <view class="record-heading"><text class="section-title">{{state.detail?state.detail.hospitalName:'新建历史补录'}}</text><text class="help">{{state.detail?state.detail.orderNo+' · '+historicalStatus(state.detail):'填写当前负责医院的历史资料'}}</text></view><text v-if="!writable" class="notice">当前记录只读，可查阅附件、核实和金额更正记录。</text><text v-if="state.conflict" class="warning help">资料版本变化，本次输入已保留。放弃本次修改后可载入最新保存稿，再核对差异。</text>
   <view class="section"><text class="section-title">01　订单与当时账期</text><view class="form-grid"><label class="wide"><text>医院 *</text><picker :range="formHospitals.map(h=>h.name)" :value="Math.max(0,formHospitals.findIndex(h=>h.id===state.form.hospitalId))" :disabled="fieldsLocked||!!state.detail" @change="state.form.hospitalId=formHospitals[picked($event)].id"><view class="picker">{{state.detail?.hospitalName||formHospitals.find(h=>h.id===state.form.hospitalId)?.name||'请选择当前负责医院'}} ›</view></picker></label><label><text>原纸单编号</text><input v-model="state.form.originalOrderNo" maxlength="100" :disabled="fieldsLocked" placeholder="未知留空"/></label><label><text>原经办人</text><input v-model="state.form.originalHandler" maxlength="200" :disabled="fieldsLocked" placeholder="未知留空"/></label><label><text>实际接收日期 *</text><picker mode="date" :value="state.form.receivedDate" :end="historicalToday()" :disabled="fieldsLocked" @change="state.form.receivedDate=dateValue($event)"><view class="picker">{{state.form.receivedDate||'待核实'}} ›</view></picker><button v-if="state.form.receivedDate&&draftWritable" size="mini" :disabled="fieldsLocked" @click="state.form.receivedDate=''">清空</button></label><label><text>原账期 / 自然日 *</text><input v-model="state.form.originalTermDays" type="number" maxlength="4" :disabled="fieldsLocked" placeholder="未知留空"/></label><label class="wide"><text>实际确认 / 知悉日期</text><picker mode="date" :value="state.form.confirmedDate" :end="historicalToday()" :disabled="fieldsLocked" @change="state.form.confirmedDate=dateValue($event)"><view class="picker">{{state.form.confirmedDate||'未知，不分配确认日期趋势'}} ›</view></picker><button v-if="state.form.confirmedDate&&draftWritable" size="mini" :disabled="fieldsLocked" @click="state.form.confirmedDate=''">清空</button></label></view><text class="help">原账期未知时，不套用默认值或推定到期日；实际业务日期与补录时间分开保存。</text></view>
   <view class="section"><view class="row-heading"><text class="section-title">02　采购药品与数量</text><button v-if="draftWritable" size="mini" :disabled="fieldsLocked||state.form.lines.length>=200" @click="addLine">＋ 增加</button></view><text class="help">共 {{state.form.lines.length}} / 200 行，每页 10 行。仅 kg；未知确认量不按采购量补齐，单价可独立留存。</text><view v-for="entry in visibleLines" :key="entry.line.id||entry.index" class="line-editor"><view class="row-heading"><text class="strong">第 {{entry.index+1}} 行</text><button v-if="draftWritable" size="mini" :disabled="fieldsLocked" @click="removeLine(entry.index)">移除</button></view><view class="form-grid"><label class="wide"><text>品名 *</text><input v-model="entry.line.name" maxlength="100" :disabled="fieldsLocked"/></label><label><text>规格</text><input v-model="entry.line.spec" maxlength="200" :disabled="fieldsLocked" placeholder="有则填写"/></label><label><text>需求 kg *</text><input v-model="entry.line.quantity" type="digit" :disabled="fieldsLocked" placeholder="待核实"/></label><label class="wide"><text>供货状态</text><picker :range="supplyOptions.map(s=>s[1])" :value="Math.max(0,supplyOptions.findIndex(s=>s[0]===entry.line.supplyStatus))" :disabled="fieldsLocked" @change="supply(entry.index,$event)"><view class="picker">{{supplyOptions.find(s=>s[0]===entry.line.supplyStatus)?.[1]}} ›</view></picker></label><label><text>确认 kg</text><input v-model="entry.line.confirmedQuantity" type="digit" :disabled="fieldsLocked||entry.line.supplyStatus!=='priced'" placeholder="未知留空"/></label><label><text>最终单价 / 元</text><input v-model="entry.line.unitPrice" type="digit" :disabled="fieldsLocked||entry.line.supplyStatus==='missing'" placeholder="未知留空"/></label></view></view><view class="pagination"><button size="mini" :disabled="linePage<=1" @click="linePage--">上一组明细</button><text>{{linePage}} / {{linePages}}</text><button size="mini" :disabled="linePage>=linePages" @click="linePage++">下一组明细</button></view></view>
   <view class="section"><text class="section-title">03　最终金额与历史已收</text><view class="form-grid"><label><text>最终确认金额 / 元 *</text><input v-model="state.form.finalAmount" type="digit" :disabled="fieldsLocked" placeholder="允许 0，未知留空"/></label><label><text>历史累计已收 / 元 *</text><input v-model="state.form.openingPaidAmount" type="digit" :disabled="fieldsLocked" placeholder="未收填 0，未知留空"/></label></view><text class="help">历史累计已收不虚构逐笔支付日期；0 元不创建回款记录。后续新回款到台账逐笔登记，避免重复记旧款。</text></view>
   <view class="section"><text class="section-title">04　首次核实依据与说明</text><label><text>核实依据 *</text><textarea v-model="state.form.verificationBasis" maxlength="2000" :disabled="fieldsLocked" placeholder="医院账本、对账资料等核实依据"/></label><label><text>核实说明 *</text><textarea v-model="state.form.verificationNote" maxlength="2000" :disabled="fieldsLocked" placeholder="已核实事实及仍未知的逐行结果或日期"/></label><text class="help">两项文字核实时必填；原纸单遗失可无附件。</text></view>
   <view v-if="state.detail" class="section"><SourceFiles :key="state.detail.orderId" ref="sources" :reference="{kind:'historical_order',orderId:state.detail.orderId}" :readonly="!writable||state.detail.verificationStatus==='verified'&&!state.correctionOpen" :locked="!!locked||state.working||recovering||!!pending||!!state.review" @busy-changed="childBusy=$event" @failure="emit('failure',$event)"/><template v-if="files.length"><text class="strong">{{state.correctionOpen?'本次更正佐证材料（可选）':'首次核实佐证材料（可选）'}}</text><view v-for="f in files" :key="f.id" class="evidence" @click="toggleEvidence(f.id)"><checkbox :checked="evidence.includes(f.id)" :disabled="blocked||!!state.review||!writable||state.detail.verificationStatus==='verified'&&!state.correctionOpen"/><text>{{f.fileName}}</text></view></template></view><text v-else class="help">先保存草稿后可上传附件；无附件也可按规则核实。</text>
   <view class="coverage"><text class="strong">核实及指标范围</text><text class="help">{{coverage.message}}</text><text class="help">{{coverage.allMissing?'明确全部缺货，核实后不建立应收。':'逐行结果未知不阻止符合条件的历史单核实，需求与最终金额正常纳入。'}}</text><template v-if="state.detail?.receivable"><text class="fact">当前应收 {{state.detail.receivable.amount}} 元</text><text class="fact">有效已收 {{state.detail.receivable.paid}} 元</text><text class="fact">未收余额 {{state.detail.receivable.balance}} 元</text><text class="fact">当前到期日 {{state.detail.receivable.dueDate}}</text></template><text v-else class="help">{{state.detail?.verificationStatus==='verified'?'明确全部缺货，无应收。':'尚未核实，不纳入正式应收、提醒及统计。'}}</text></view>
   <view v-if="draftWritable" class="actions"><button :disabled="blocked||!!state.review" @click="safely(()=>controller.save())">保存草稿</button><button class="primary" :disabled="blocked||dirty||!state.detail||!!state.review" @click="guard(()=>controller.reviewVerification())">核实并纳入台账</button><text class="help">{{dirty||!state.detail?'请先保存草稿再复核。':'复核后明确确认，不会直接入账。'}}</text></view>
   <view v-if="state.detail?.verificationStatus==='verified'" class="section"><text class="section-title">金额录入更正与完整记录</text><text class="help">原核实金额 {{state.detail.originalVerifiedAmount}} 元；原核实依据和时间保留。仅更正录入错误，不执行实际退款。</text><button v-if="writable&&state.detail.receivable&&!state.correctionOpen" :disabled="blocked" @click="safely(()=>controller.beginCorrection())">读取最新已收，发起金额更正</button><view v-if="state.correctionOpen" class="correction-form"><label><text>更正后金额 / 元 *</text><input v-model="state.correction.newAmount" type="digit" :disabled="blocked||!!state.review"/></label><text class="help">最新有效已收 {{state.detail.receivable?.paid}} 元，提交时服务端再次核对。</text><label><text>更正原因 *</text><textarea v-model="state.correction.reason" maxlength="500" :disabled="blocked||!!state.review"/></label><label><text>本次独立核实依据 *</text><textarea v-model="state.correction.verificationBasis" maxlength="2000" :disabled="blocked||!!state.review"/></label><label><text>本次独立核实说明 *</text><textarea v-model="state.correction.verificationNote" maxlength="2000" :disabled="blocked||!!state.review"/></label><button class="primary" :disabled="blocked||!!state.review" @click="guard(()=>controller.reviewCorrection())">复核本次金额更正</button></view><view v-for="change in state.detail.corrections" :key="change.id" class="audit"><text class="strong">{{change.beforeAmount}} → {{change.afterAmount}} 元</text><text class="help">原核实 {{change.originalVerifiedAmount}} 元 · 当时有效已收 {{change.paidAtCorrection}} 元 · 更正后余额 {{moneyDifference(change.afterAmount,change.paidAtCorrection)}} 元</text><text class="fact">原因：{{change.reason}}</text><text class="fact">本次核实依据：{{change.verificationBasis}}</text><text class="fact">本次核实说明：{{change.verificationNote}}</text><text class="help">{{change.recordedByName}} · {{formatBeijingTimestamp(change.recordedAt)}} · 附件 {{change.evidenceFileIds.length}} 份</text></view><text v-if="!state.detail.corrections.length" class="help">尚无金额更正记录。</text></view>
   <view v-if="state.detail" class="section"><text class="section-title">补录与核实留痕</text><text class="help">补录人 {{state.detail.createdBy}}
补录时间 {{formatBeijingTimestamp(state.detail.createdAt)}}
核实人 {{state.detail.verifiedBy||'尚未核实'}}
核实时间 {{formatBeijingTimestamp(state.detail.verifiedAt)}}</text></view>
   <view v-if="state.detail&&draftWritable" class="section"><text class="section-title">作废未核实历史草稿</text><label><text>作废原因</text><textarea v-model="state.voidReason" maxlength="500" :disabled="blocked||!!state.review"/></label><button :disabled="blocked||!!state.review" @click="guard(()=>controller.reviewVoid())">复核作废</button></view>
  </template>
  <view v-if="state.review" class="review-overlay"><scroll-view scroll-y class="review-dialog"><view class="review-body"><text class="eyebrow">提交前复核</text><text class="section-title">{{state.review.title}}</text><view v-for="(fact,i) in state.review.facts" :key="i" class="review-fact"><text class="help">{{fact[0]}}</text><text class="fact">{{fact[1]}}</text></view><text class="notice">{{state.review.impact}}</text><view class="evidence" @click="!busy&&(ack=!ack)"><checkbox :checked="ack" :disabled="busy"/><text>已核对本次事实、金额及未知范围，确认提交。</text></view><view class="actions"><button :disabled="busy" @click="state.review=null">返回修改</button><button class="primary" :disabled="blocked||!ack" @click="commit">{{state.working?'正在提交…':'确认提交'}}</button></view></view></scroll-view></view>
  <text class="footnote">真实微信手感、真实 COS 配置及外部环境验收仍待完成。</text>
 </view>
